<template>
 <el-dialog class="warehouse-handover-dialog" v-model="visible" title="加工产出及全部余料交接" width="min(1160px,96vw)" :close-on-click-modal="false" :show-close="!busy&&!uncertain" :close-on-press-escape="!busy&&!uncertain" @closed="!visible&&clear()">
  <el-form v-loading="loading" label-position="top" :disabled="busy||uncertain">
   <div class="handover-context"><el-form-item label="工厂"><el-select v-model="factoryId" @change="factoryChanged()"><el-option v-for="f in factories" :key="f.id" :value="f.id" :label="f.name"/></el-select></el-form-item><el-form-item label="本人已实领的加工批次"><el-select v-model="batchId" filterable @change="loadBatch"><el-option v-for="b in batches" :key="b.id||b.batchId" :value="String(b.batchId||b.id)" :label="b.orderNo+' / '+b.batchNo+' / '+b.processName"/></el-select></el-form-item><el-form-item label="交接日期"><el-date-picker v-model="date" type="date" value-format="YYYY-MM-DD"/></el-form-item></div>
   <template v-if="context">
    <p>{{(context.material??context.product)?.name}} · {{context.customer}} · 本人实际领入 {{decimalText(ownIssued)}} g。加工称重用于损耗计算；库管验收后才入库。</p>
    <h4>{{rawOutput?'原料主产出':'本人工序产出'}}</h4><p v-if="rawOutput">按净重入库，不登记件数。{{acidOutput?'酸洗主产出须选择同金属目标物料编码。':'前处理产出保留真实来源资格。'}}</p>
    <el-button @click="addOutput">追加产出仓库</el-button>
    <el-table :data="outputs" border>
     <el-table-column label="入库仓库" min-width="170"><template #default="{row}"><el-select v-model="row.warehouseId"><el-option v-for="w in warehouses" :key="w.id" :value="w.id" :label="w.name"/></el-select></template></el-table-column>
     <el-table-column label="指定仓管员" min-width="170"><template #default="{row}"><el-select v-model="row.keeperId" filterable><el-option v-for="p in people" :key="p.id" :value="p.id" :label="personLabel(p)"/></el-select></template></el-table-column>
     <el-table-column v-if="rawOutput" label="产出物料编码" min-width="210"><template #default="{row}"><el-select v-model="row.referenceId" filterable aria-label="原料产出物料编码"><el-option v-for="m in outputMaterials" :key="m.id" :value="m.id" :label="m.code+' / '+m.name"/></el-select></template></el-table-column><el-table-column label="加工称重（g）" min-width="155"><template #default="{row}"><BusinessDecimalInput v-model="row.netWeight" aria-label="加工称重（g）" inputmode="decimal"/></template></el-table-column>
     <el-table-column v-if="!rawOutput" :label="weightMode?'参考件数（可空）':'实际产出件数'" min-width="150"><template #default="{row}"><el-input v-model="row.quantity" inputmode="numeric"/></template></el-table-column>
     <el-table-column label="操作" width="80"><template #default="{$index}"><el-button link type="danger" @click="outputs.splice($index,1)">移除</el-button></template></el-table-column>
    </el-table>
    <h4>全部余料</h4><el-radio-group v-model="residualMode"><el-radio value="RETURNED">本次全部余料一并交接</el-radio><el-radio value="NONE">实物核对无余料</el-radio></el-radio-group>
    <template v-if="residualMode==='RETURNED'">
     <p>未用原料及未加工半成品选择本人原实领明细，退回原仓、原归属。加工形成粉料或碎料另选回收原料；不能把未加工半成品改成原料。</p>
     <el-button @click="addReturn('SOURCE')">追加未用料</el-button><el-button @click="addReturn('RECOVERY')">追加加工回收原料</el-button>
     <section v-for="(row,index) in returns" :key="row.key" class="return-row">
      <div class="return-heading"><strong>{{row.mode==='SOURCE'?'未用原料 / 未加工半成品':'加工回收粉料 / 碎料'}}</strong><el-button link type="danger" @click="returns.splice(index,1)">移除</el-button></div>
      <div class="handover-context">
       <el-form-item v-if="row.mode==='SOURCE'" label="本人原实领明细"><el-select v-model="row.sourceLineId" filterable @change="selectSource(row)"><el-option v-for="s in ownSources" :key="s.lineId" :value="s.lineId" :label="s.orderNo+' / '+s.code+' / '+decimalText(s.netWeight)+'g'"/></el-select></el-form-item>
       <el-form-item v-else label="回收原料编码"><el-select v-model="row.referenceId" filterable><el-option v-for="m in sameMetalMaterials" :key="m.id" :value="m.id" :label="m.code+' / '+m.name"/></el-select></el-form-item>
       <el-form-item v-if="row.mode==='RECOVERY'" label="材料归属"><el-select v-model="row.materialOwnership"><el-option label="客户料" value="CUSTOMER"/><el-option label="工厂自有料" value="FACTORY"/></el-select></el-form-item>
       <el-form-item label="还库仓库"><el-select v-model="row.warehouseId" :disabled="row.mode==='SOURCE'"><el-option v-for="w in warehouses" :key="w.id" :value="w.id" :label="w.name"/></el-select></el-form-item>
       <el-form-item label="指定仓管员"><el-select v-model="row.keeperId" filterable><el-option v-for="p in people" :key="p.id" :value="p.id" :label="personLabel(p)"/></el-select></el-form-item>
       <el-form-item label="加工人还料称重（g）"><BusinessDecimalInput v-model="row.netWeight" aria-label="加工称重（g）" inputmode="decimal"/></el-form-item>
       <el-form-item v-if="row.category==='SEMI'" :label="row.measurementMode==='WEIGHT'?'参考件数（可空）':'未加工半成品件数'"><el-input v-model="row.quantity" inputmode="numeric"/></el-form-item>
      </div>
     </section>
    </template>
    <el-form-item label="交接说明 / 回收原因"><el-input v-model="reason" type="textarea" maxlength="500" show-word-limit/></el-form-item>
    <el-checkbox v-model="checked">已逐项核对本人的全部产出及全部余料，或明确无余料</el-checkbox>
    <p>本次申报产出及余料合计：{{decimalText(declaredTotal)}} g。库管须使用指定账号独立称重验收。</p>
   </template>
   <p v-if="refreshFailed" role="status">更新检查失败，当前资料可能过期。</p><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
  </el-form>
  <template #footer><el-button v-if="uncertain" type="primary" :loading="busy" @click="retryRequest">重试原请求</el-button><el-button :disabled="busy||uncertain" @click="visible=false">关闭</el-button><el-button v-if="context" :disabled="busy||uncertain" @click="factoryChanged(batchId)">重新加载批次</el-button><el-button type="primary" :loading="busy" :disabled="!context?.canSubmit||loading||needsReload||uncertain" @click="save">本人提交全部交接</el-button></template>
 </el-dialog>
</template>
<script setup lang="ts">
import {ref,computed,onBeforeUnmount} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessage} from 'element-plus'
import BusinessDecimalInput from '@/components/BusinessDecimalInput.vue'
import useUserStore from '@/store/modules/user'
import {useActionPermission} from '@/composables/useActionPermission'
import {warehouseOptions,warehouseHandoverBatches,warehouseHandoverContext,warehouseFlowAction,type Row} from '@/api/metal/warehouse'
import {decimalText} from '@/utils/business-decimal'
import {createUUID} from '@/utils/uuid'
import {getToken} from '@/utils/auth'
import {useInventoryRefresh} from '@/composables/useInventoryRefresh'
import {personLabel} from '@/utils/person-label'
const emit=defineEmits<{saved:[flowId:string]}>(),user=useUserStore(),permission=useActionPermission()
const visible=ref(false),loading=ref(false),busy=ref(false),needsReload=ref(false),error=ref(''),factoryId=ref(''),batchId=ref(''),date=ref(''),reason=ref(''),checked=ref(false),residualMode=ref('NONE'),context=ref<Row>(),factories=ref<Row[]>([]),batches=ref<Row[]>([]),warehouses=ref<Row[]>([]),people=ref<Row[]>([]),materials=ref<Row[]>([]),outputs=ref<Row[]>([]),returns=ref<Row[]>([])
const uncertain=ref(false);let pendingRequest:{suffix:string;payload:Row}|undefined,baseline='',optionBaseline='';
const stamp=(v:Row)=>JSON.stringify([v.version,v.status,v.canSubmit,v.sources,v.flow?.version,v.flow?.status,(v.flow?.groups??[]).map((g:Row)=>[g.id,g.status,g.processorId])]);
const identity=()=>JSON.stringify([user.token,String(user.id),[...user.permissions].sort()]);let openedIdentity=''
const sessionCurrent=()=>user.sessionReady&&!!user.token&&user.token===getToken()&&openedIdentity===identity()
let epoch=0,disposed=false,attemptBody='',attemptId='';const current=(round:number)=>()=>!disposed&&visible.value&&round===epoch&&sessionCurrent()
const ownSources=computed(()=>(context.value?.sources??[]).filter((s:Row)=>String(s.recipientId)===String(user.id)&&String(s.confirmedBy)===String(user.id)))
const ownIssued=computed(()=>ownSources.value.reduce((sum:number,s:Row)=>sum+Number(s.netWeight),0)),weightMode=computed(()=>context.value?.measurementMode==='WEIGHT')
const rawOutput=computed(()=>context.value?.outputType==='RAW_PROCESS_IN'||context.value?.outputStage==='RAW'),acidOutput=computed(()=>context.value?.processRole==='ACID_WASH')
const sameMetalMaterials=computed(()=>materials.value.filter(m=>String(m.metalTypeId)===String(context.value?.metalTypeId??context.value?.material?.metalTypeId??context.value?.product?.metalTypeId)))
const outputMaterials=computed(()=>sameMetalMaterials.value)
const declaredTotal=computed(()=>[...outputs.value,...(residualMode.value==='RETURNED'?returns.value:[])].reduce((sum:number,r:Row)=>sum+(Number(r.netWeight)||0),0))
function clear(){epoch++;busy.value=false;loading.value=false;uncertain.value=false;pendingRequest=undefined;context.value=undefined;outputs.value=[];returns.value=[];attemptId='';attemptBody='';error.value=''}
async function open(batch?:string){if(busy.value||uncertain.value||!user.sessionReady||!user.token||user.token!==getToken())return;clear();openedIdentity=identity();visible.value=true;date.value=new Date().toLocaleDateString('sv-SE');reason.value='';checked.value=false;residualMode.value='NONE';needsReload.value=false;batchId.value='';const round=epoch;loading.value=true;try{const r=await warehouseOptions('factories',undefined,undefined,current(round));if(!current(round)())return;factories.value=r.data;factoryId.value=r.data[0]?.id??'';await factoryChanged(batch)}catch(e:any){if(current(round)())error.value=e?.message||'交接资料加载失败'}finally{if(current(round)())loading.value=false}}
async function factoryChanged(preferred?:string){if(busy.value||uncertain.value)return;const round=++epoch;context.value=undefined;batchId.value='';outputs.value=[];returns.value=[];if(!factoryId.value)return;loading.value=true;try{const values=await Promise.all([warehouseHandoverBatches(factoryId.value,current(round)),warehouseOptions('warehouses',factoryId.value,undefined,current(round)),warehouseOptions('people',factoryId.value,undefined,current(round)),warehouseOptions('materials',factoryId.value,undefined,current(round))]);if(!current(round)())return;[batches.value,warehouses.value,people.value,materials.value]=values.map(r=>r.data);optionBaseline=JSON.stringify(values.slice(1).map(r=>r.data));if(preferred){batchId.value=preferred;await loadBatch()}}catch(e:any){if(current(round)())error.value=e?.message||'候选加载失败'}finally{if(current(round)())loading.value=false}}
async function loadBatch(){if(busy.value||uncertain.value)return;const round=++epoch;context.value=undefined;outputs.value=[];returns.value=[];checked.value=false;attemptId='';attemptBody='';error.value='';if(!batchId.value){loading.value=false;return}loading.value=true;try{const r=await warehouseHandoverContext(batchId.value,current(round));if(!current(round)())return;context.value=r.data;baseline=stamp(r.data);outputs.value=[];returns.value=[];checked.value=false;needsReload.value=false;attemptId='';attemptBody='';const ownGroups=(r.data.flow?.groups??[]).filter((g:Row)=>String(g.processorId)===String(user.id));if(ownGroups.length){for(const g of ownGroups)for(const l of g.lines){if(['RAW_PROCESS_IN','SEMI_IN','FINISHED_IN'].includes(g.type))outputs.value.push({referenceId:l.line.referenceId,warehouseId:g.warehouseId,keeperId:g.keeperId,netWeight:l.processorWeight,quantity:l.line.referenceQuantity??l.line.quantity??''});else{const source=(r.data.sources??[]).find((s:Row)=>String(s.lineId)===String(l.line.sourceLineId));const row:Row={...l.line,key:createUUID(),mode:g.type==='PROCESS_RAW_RETURN'?'RECOVERY':'SOURCE',warehouseId:g.warehouseId,keeperId:g.keeperId,netWeight:l.processorWeight,measurementMode:source?.measurementMode,quantity:l.line.referenceQuantity??l.line.quantity??''};returns.value.push(row)}}residualMode.value=returns.value.length?'RETURNED':'NONE'}else addOutput()}catch(e:any){if(current(round)())error.value=e?.message||'批次加载失败'}finally{if(current(round)())loading.value=false}}
function addOutput(){outputs.value.push({referenceId:acidOutput.value?'':context.value?.materialId,warehouseId:warehouses.value[0]?.id??'',keeperId:'',netWeight:'',quantity:weightMode.value?'':context.value?.plannedQuantity??''})}
function addReturn(mode:string){returns.value.push({key:createUUID(),mode,category:'RAW',sourceLineId:'',referenceId:'',materialOwnership:'',warehouseId:warehouses.value[0]?.id??'',keeperId:'',netWeight:'',quantity:''})}
function selectSource(row:Row){const source=ownSources.value.find((s:Row)=>s.lineId===row.sourceLineId);if(source)Object.assign(row,{category:source.category,warehouseId:source.warehouseId,measurementMode:source.measurementMode,materialOwnership:source.materialOwnership,quantity:source.measurementMode==='WEIGHT'?'':source.quantity??''})}
async function save(){if(!current(epoch)()||!context.value||String(context.value.batchId)!==String(batchId.value)||busy.value||loading.value||needsReload.value||uncertain.value)return;if(!checked.value||!outputs.value.length||residualMode.value==='RETURNED'&&!returns.value.length){error.value='请核对产出、全部余料及实物确认';return}const documents:Row[]=[];const add=(row:Row,type:string,line:Row)=>{let group=documents.find(g=>g.type===type&&g.warehouseId===row.warehouseId&&g.keeperId===row.keeperId);if(!group){group={type,warehouseId:row.warehouseId,keeperId:row.keeperId,lines:[]};documents.push(group)}group.lines.push(line)};
 const outputType=rawOutput.value?'RAW_PROCESS_IN':context.value.outputType??(context.value.isLast===false?'SEMI_IN':'FINISHED_IN');
 if(rawOutput.value&&outputs.value.some(r=>!outputMaterials.value.some(m=>String(m.id)===String(r.referenceId)))){error.value='请选择同金属的目标物料编码';return}
 for(const row of outputs.value)add(row,outputType,{category:rawOutput.value?'RAW':outputType==='SEMI_IN'?'SEMI':'FINISHED',referenceId:rawOutput.value?row.referenceId:context.value.productId,netWeight:row.netWeight,quantity:rawOutput.value||weightMode.value?0:Number(row.quantity),referenceQuantity:!rawOutput.value&&weightMode.value&&row.quantity!==''?Number(row.quantity):null});
 for(const row of residualMode.value==='RETURNED'?returns.value:[]){const semi=row.category==='SEMI',byWeight=semi&&row.measurementMode==='WEIGHT';add(row,row.mode==='RECOVERY'?'PROCESS_RAW_RETURN':semi?'SEMI_RETURN':'RAW_RETURN',{category:semi?'SEMI':'RAW',sourceLineId:row.mode==='SOURCE'?row.sourceLineId:null,referenceId:row.mode==='RECOVERY'?row.referenceId:null,materialOwnership:row.materialOwnership||null,netWeight:row.netWeight,quantity:semi&&!byWeight?Number(row.quantity):0,referenceQuantity:byWeight&&row.quantity!==''?Number(row.quantity):null})}
 if(documents.some(g=>!g.warehouseId||!g.keeperId||g.lines.some((l:Row)=>!/^\d+(\.\d{1,2})?$/.test(String(l.netWeight))||Number(l.netWeight)<=0||l.quantity<0||!Number.isInteger(l.quantity)))){error.value='请填写合法重量、仓库、仓管员及产出信息';return}if(returns.value.some(r=>r.mode==='RECOVERY')&&!reason.value.trim()){error.value='请填写加工回收原因';return}
 const payload={version:context.value.version,orderDate:date.value,physicalChecked:true,residualMode:residualMode.value,reason:reason.value,documents},serialized=JSON.stringify(payload);if(serialized!==attemptBody){attemptBody=serialized;attemptId=createUUID()}pendingRequest={suffix:'handover/'+batchId.value,payload:JSON.parse(JSON.stringify({requestId:attemptId,...payload}))};await retryRequest()}
async function retryRequest(){if(!current(epoch)()||busy.value||!pendingRequest)return;const round=epoch,attempt=pendingRequest;busy.value=true;error.value='';try{const r=await warehouseFlowAction(attempt.suffix,attempt.payload,current(round));if(!current(round)()||pendingRequest!==attempt)return;uncertain.value=false;pendingRequest=undefined;visible.value=false;ElMessage.success('加工交接已提交，等待指定库管验收');emit('saved',String(r.data.id))}catch(e:any){if(current(round)()&&pendingRequest===attempt){uncertain.value=typeof e?.code!=='number';if(!uncertain.value)pendingRequest=undefined;error.value=uncertain.value?'提交结果未知，请重试原请求确认结果；全部称重已保留。':e?.message||'提交失败，输入已保留';if(!uncertain.value&&/版本|刷新|重新加载/.test(error.value))needsReload.value=true}}finally{if(current(round)())busy.value=false}}
const {failed:refreshFailed}=useInventoryRefresh(async ctx=>{if(!factoryId.value)return;const round=epoch,factory=factoryId.value,valid=()=>ctx.isCurrent()&&current(round)()&&factory===factoryId.value&&!context.value;const r=await warehouseHandoverBatches(factory,valid,true);if(valid())batches.value=r.data},computed(()=>!!context.value),{allowed:()=>visible.value&&permission.hasAny(['metal:warehouse-order:handover','metal:warehouse-order:query','metal:warehouse-order:accept','metal:warehouse-order:add']),reset:()=>{visible.value=false;clear()}},{paused:computed(()=>busy.value||loading.value||uncertain.value),probe:async ctx=>{if(!context.value)return;const round=epoch,id=batchId.value,factory=factoryId.value,valid=()=>ctx.isCurrent()&&current(round)()&&batchId.value===id&&!busy.value&&!loading.value&&!uncertain.value;const r=await warehouseHandoverContext(id,valid,true);if(!valid())return;const opts=await Promise.all(['warehouses','people','materials'].map(k=>warehouseOptions(k,factory,undefined,valid,undefined,true)));if(valid()&&(stamp(r.data)!==baseline||JSON.stringify(opts.map(o=>o.data))!==optionBaseline)){needsReload.value=true;error.value='业务资料已更新，请重新加载批次并核对；全部称重已保留。'}}})

permission.onChange(()=>{visible.value=false;clear()});onBeforeRouteLeave(()=>{if(busy.value||uncertain.value)return false;visible.value=false;clear()});onBeforeRouteUpdate(()=>{if(busy.value||uncertain.value)return false;visible.value=false;clear()});onBeforeUnmount(()=>{disposed=true;epoch++});defineExpose({open,isOpen:visible})
</script>
<style scoped>.handover-context{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.handover-context :deep(.el-select),.handover-context :deep(.el-date-editor){width:100%}.return-row{padding:14px;margin:14px 0;border:1px solid #dcdfe6;border-radius:6px}.return-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}h4{margin:20px 0 12px}.el-table{margin-top:12px}@media(max-width:768px){.handover-context{grid-template-columns:1fr}.return-row{padding:10px}}</style>

<style scoped>.warehouse-handover-dialog :deep(.el-table .cell),.warehouse-handover-dialog :deep(.el-table input){text-align:center}</style>
